import gzip
from html import escape
from format_lecon import R,paras
def q(t):return '<blockquote><p>« '+escape(t.strip())+' »</p></blockquote>'
def zone(s,a,b):
 i=s.index(a)+len(a);return q(s[i:s.index(b,i)])
def mestinon(l):
 s=gzip.open(R/'ressources_ia/aips/fi_fr/19943.txt.gz','rt').read()
 dose=zone(s,'\nMyasthénie grave\n','\nInstructions posologiques particulières\n')
 ped=s[s.index('\nPédiatrie\n')+len('\nPédiatrie\n'):s.index('\nEn cas de myasthénie néonatale')]
 admin=next(x for x in s.splitlines() if x.startswith('Les comprimés retard sont à prendre'))
 body=paras('Mestinon contient du bromure de pyridostigmine, inhibiteur de l’acétylcholinestérase à effet symptomatique. La fiche commune décrit comprimé de 10 mg (n° 19943), dragée de 60 mg (n° 19945) et comprimé retard de 180 mg (n° 56387). Les formes ne sont pas interchangeables sans adaptation.', 'Repères adultes de la fiche suisse pour myasthénie grave, citation exacte :')+dose+paras('Ces repères larges ne sont pas une dose initiale à appliquer systématiquement, ni une consigne d’escalade devant une dysphagie. La dose et les horaires doivent être titrés individuellement par le prescripteur selon réponse, tolérance et fonction rénale. Une aggravation bulbaire ou respiratoire exige une évaluation urgente.', 'Fonction rénale, citation AIPS :')+zone(s,'\nPatients souffrant de maladies rénales\n','\nPédiatrie\n')+paras('Pédiatrie, limites et préparation, citation AIPS :')+q(ped)+paras('Le schéma adulte ne doit pas être extrapolé à l’enfant. Une myasthénie néonatale ou un syndrome congénital demande une expertise distincte ; aucun protocole néonatal n’est fourni ici.', 'Administration de la forme retard, citation AIPS :')+q(admin)+paras('La consigne de liquide de la fiche suppose une déglutition sûre. Elle ne doit pas être appliquée en cas de prise orale dangereuse. Le partage autorisé facilite la déglutition et ne produit pas deux doses équivalentes ; ne pas broyer ou fragmenter davantage. Organiser une autre forme ou voie avec l’équipe.', 'Contre-indications, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde et précautions\n')+paras('Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nFertilité\n')+paras('Effets muscariniques possibles : diarrhée, crampes abdominales, salivation, sécrétions bronchiques, bradycardie et myosis. Des fasciculations et une faiblesse accrue peuvent signaler un excès cholinergique. Ne pas augmenter seul le traitement devant une faiblesse.', 'Prudence notamment en cas d’asthme, de bronchopneumopathie obstructive, de trouble du rythme ou d’insuffisance rénale. Vérifier les excipients selon la présentation et les maladies héréditaires du métabolisme des sucres.', 'Revoir les médicaments qui affectent la transmission neuromusculaire, dont certains antibiotiques et anesthésiques. La méthylcellulose peut diminuer l’absorption. L’introduction de corticoïdes peut initialement aggraver la myasthénie et demande une stratégie spécialisée.', 'Lors d’une crise, la protection respiratoire et le traitement hospitalier priment. La gestion des anticholinestérasiques dépend notamment des sécrétions et de la ventilation ; le schéma oral de maintien ne doit pas être appliqué comme protocole de réanimation.')
 return l.subwindow('mestinon','Mestinon : repères AIPS et précautions',body,(30,))
def jorveza(l):
 s=gzip.open(R/'codex-LOTS-html/LOT_023/evidence/JORVEZA_66999_officiel.txt.gz','rt').read()
 body=paras('Jorveza, n° Swissmedic 66999 : budésonide, glucocorticoïde à action locale œsophagienne, en comprimés orodispersibles de 0,5 mg ou 1 mg. L’information professionnelle suisse consultée indique le traitement de l’œsophagite à éosinophiles chez l’adulte.', 'Induction, citation AIPS :')+zone(s,"\nTraitement d'induction\n","\nTraitement d'entretien\n")+paras('Entretien, citation AIPS :')+zone(s,"\nTraitement d'entretien\n",'\nPopulations particulières de patients\n')+paras('Insuffisance rénale, citation AIPS :')+zone(s,'\nTroubles de la fonction rénale\n','\nTroubles de la fonction hépatique\n')+paras('Insuffisance hépatique, citation AIPS :')+zone(s,'\nTroubles de la fonction hépatique\n','\nEnfants et adolescents\n')+paras('Pédiatrie, citation AIPS :')+zone(s,'\nEnfants et adolescents\n',"\nMode d'administration\n")+paras('Ne pas extrapoler ce schéma adulte à l’enfant. Le choix pédiatrique doit être établi par l’équipe spécialisée, avec identification explicite de tout usage hors information professionnelle.', 'Administration, citation AIPS :')+zone(s,"\nMode d'administration\n",'\nContre-indications\n')+paras('Le contact de la salive chargée de médicament avec l’œsophage est recherché. Ne pas employer ce traitement pour tenter de débloquer une impaction ; l’impossibilité d’avaler la salive relève de l’urgence.', 'Contre-indication, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde et précautions\n')+paras('Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nFertilité\n')+paras('Les candidoses buccales, pharyngées et œsophagiennes sont des effets indésirables importants. Une candidose symptomatique demande une évaluation ; selon la fiche, un antifongique peut être prescrit tout en poursuivant Jorveza. Ne pas ajouter un antifongique sans vérifier les interactions.', 'Les effets systémiques des corticoïdes restent possibles : suppression surrénalienne, troubles glycémiques, osseux, oculaires ou psychiatriques. Surveiller le terrain et l’exposition à d’autres corticoïdes. Un trouble visuel demande un avis ophtalmologique ; une chirurgie ou un stress majeur peut nécessiter une couverture corticoïde adaptée par le médecin.', 'Éviter l’association aux inhibiteurs puissants du CYP3A, notamment certains azolés, ritonavir, cobicistat et clarithromycine, ainsi qu’au jus de pamplemousse, sauf décision justifiée avec surveillance. Vérifier aussi risque d’hypokaliémie avec diurétiques et glucosides cardiotoniques.', 'Les infections peuvent être plus sévères ou masquées. Éviter les vaccins vivants concomitants et évaluer le statut face à varicelle, zona et rougeole selon le contexte. La balance bénéfice-risque et la surveillance guident l’entretien, sans arrêt ou prolongation automatique fondés uniquement sur les symptômes.')
 return l.subwindow('jorveza','Jorveza : doses et sécurité suisses',body,(19,))
def antramups(l):
 s=gzip.open(R/'ressources_ia/aips/fi_fr/54380.txt.gz','rt').read()
 dose=s[s.index('\nUlcère gastrique, œsophagite de reflux\n')+len('\nUlcère gastrique, œsophagite de reflux\n'):].split('\n')[0]
 ent=next(x for x in s.splitlines() if x.startswith('Pour la prophylaxie des récidives de l’œsophagite'))
 body=paras('Antramups, n° Swissmedic 54380, contient de l’oméprazole, inhibiteur de la pompe à protons, en comprimés de 10, 20 ou 40 mg. La fiche suisse couvre l’œsophagite de reflux et sa prophylaxie ; elle ne décrit pas une dilatation ni un protocole autonome de sténose peptique.', 'Dose AIPS pour œsophagite de reflux chez l’adulte et l’adolescent de plus de douze ans :')+q(dose)+paras('Prophylaxie des récidives de l’œsophagite guérie, citation AIPS :')+q(ent)+paras('L’anti-sécrétoire traite l’inflammation et le reflux associés. La durée de prévention après dilatation et l’intensité nécessaire sont décidées selon le risque de récidive ; ne pas transformer la durée de cicatrisation de l’œsophagite en date automatique d’arrêt après dilatation.', 'Pédiatrie pour œsophagite de reflux, citation AIPS :')+zone(s,'\nEn règle générale, on prescrira les posologies suivantes:\n','\nAdultes et adolescents de plus de 12 ans')+paras('Ces doses pédiatriques de reflux ne diagnostiquent pas une sténose et ne dispensent pas d’une évaluation spécialisée. Données limitées chez le très jeune nourrisson et indication stricte selon la fiche.', 'Administration en cas de difficulté de déglutition, citation AIPS :')+zone(s,'\nMode et durée de l’administration\n','\nInstructions p')+paras('Cette possibilité de dispersion exige que le patient puisse avaler le liquide ou la texture sans danger. Elle ne s’applique pas à une obstruction complète ou une prise orale interdite ; ne jamais broyer les micropellets.', 'Contre-indication, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('La fiche exclut également la prise chez les patients présentant certaines maladies héréditaires du métabolisme des sucres, liées aux excipients. Une dysphagie, un amaigrissement, des vomissements persistants ou un saignement exigent de rechercher une cause maligne au lieu de masquer les symptômes.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, Allaitement\n','\nEffet sur')+paras('Interactions : association avec clopidogrel déconseillée ; atazanavir et nelfinavir non recommandés. Vérifier aussi anticoagulants, phénytoïne, digoxine, tacrolimus et méthotrexate à forte dose. Le prescripteur adapte choix et surveillance ; un simple décalage de prise ne supprime pas l’interaction avec clopidogrel.', 'Surveiller tolérance et justification du traitement prolongé, avec attention à l’hypomagnésémie et aux facteurs de risque osseux. Suspecter une néphrite tubulo-interstitielle devant une atteinte rénale nouvelle : arrêt et prise en charge rapide selon la fiche. Une éruption photosensible avec arthralgies impose un avis et une discussion d’arrêt.', 'Aucun ajustement n’est requis pour l’insuffisance rénale selon l’AIPS, mais la biodisponibilité et la demi-vie augmentent en cas d’insuffisance hépatique. La poursuite ou l’arrêt se décident avec le prescripteur, en distinguant récidive acide, nouvelle obstruction et effet indésirable.')
 return l.subwindow('antramups','Antramups : reflux et administration adaptée',body,(11,))
